import os, stat, json, signal, sys, time

def utc():
    ns = time.time_ns()
    return time.strftime('%Y-%m-%dT%H:%M:%S', time.gmtime(ns // 1000000000)) + '.%09dZ' % (ns % 1000000000)

def timeout(_signum, _frame):
    raise TimeoutError()

signal.signal(signal.SIGALRM, timeout)
signal.alarm(5)
started = utc()
entries, missing, errors, seen = [], [], [], set()
truncated = False

def allowed(path):
    return (path.startswith('/dev/nvidia') and '/' not in path[len('/dev/'):]) or path.startswith('/dev/nvidia-caps/') or path == '/dev/dri' or path.startswith('/dev/dri/') or path in ('/dev/kfd', '/dev/dxg')

def visit(path, depth=0):
    global truncated
    if path in seen:
        return
    if len(seen) >= 128 or len(path.encode()) > 512 or depth > 16:
        truncated = True
        return
    assert allowed(path)
    seen.add(path)
    try:
        meta = os.lstat(path)
    except FileNotFoundError:
        missing.append(path)
        return
    except OSError as exc:
        errors.append({'path': path, 'errno': exc.errno})
        return
    kind = 'directory' if stat.S_ISDIR(meta.st_mode) else 'char' if stat.S_ISCHR(meta.st_mode) else 'symlink' if stat.S_ISLNK(meta.st_mode) else 'other'
    item = {'path': path, 'type': kind}
    if kind == 'char':
        item.update(major=os.major(meta.st_rdev), minor=os.minor(meta.st_rdev))
    if kind == 'symlink':
        target = os.readlink(path)
        normalized = os.path.normpath(target if target.startswith('/') else os.path.join(os.path.dirname(path), target))
        if len(target.encode()) <= 512 and len(normalized.encode()) <= 512 and allowed(normalized):
            item['symlink_target'] = target
        else:
            item['symlink_target'] = 'WITHHELD_OUTSIDE_ALLOWLIST_OR_BOUND'
    entries.append(item)
    if kind == 'directory' and (path == '/dev/nvidia-caps' or path.startswith('/dev/nvidia-caps/') or path == '/dev/dri' or path.startswith('/dev/dri/')):
        with os.scandir(path) as children:
            for child in children:
                if len(seen) >= 128:
                    truncated = True
                    break
                visit(path + '/' + child.name, depth + 1)

status = 'OBSERVED'
try:
    # Filter names only; do not stat or emit any other /dev entry.
    with os.scandir('/dev') as candidates:
        for candidate in candidates:
            if candidate.name.startswith('nvidia'):
                visit('/dev/' + candidate.name)
                if len(seen) >= 128:
                    truncated = True
                    break
    for path in ('/dev/nvidia-caps', '/dev/dri', '/dev/kfd', '/dev/dxg'):
        visit(path)
except TimeoutError:
    status = 'TIMEOUT_PARTIAL'
except OSError as exc:
    status = 'ERROR_PARTIAL'
    errors.append({'errno': exc.errno})
finished = utc()
signal.alarm(0)
result = {'status': status, 'started_utc': started, 'finished_utc': finished, 'entries': sorted(entries, key=lambda item: item['path']), 'missing_fixed_paths': sorted(set(missing)), 'errors': errors[:128], 'truncated': truncated, 'limits': {'entries': 128, 'output_bytes': 32768, 'process_alarm_seconds': 5, 'path_bytes': 512, 'symlink_target_bytes': 512, 'recursion_depth': 16}, 'method': 'lstat and directory-name enumeration; readlink only for symlinks, no symlink traversal; no device node open/read/write'}
while len((json.dumps(result, sort_keys=True) + '\n').encode()) > 32768:
    result['truncated'] = True
    if result['entries']:
        result['entries'].pop()
    elif result['errors']:
        result['errors'].pop()
    else:
        raise RuntimeError('output_bound')
print(json.dumps(result, sort_keys=True), flush=True)
sys.exit(0 if status == 'OBSERVED' and not result['truncated'] and not errors else 2)
